\coordinate (A) at (0,0);
\coordinate (C) at (3.620,2.090);
\coordinate (P) at (1.358,0);
\coordinate (Q) at (5.882,0);
\draw (A)--(Q);
\draw (A)--(C) node[midway,above left] {$19\text{ cm}$};
\draw[tickmark] (C)--(P) node[midway,left,fill=white,inner sep=1pt] {$14\text{ cm}$};
